LOCATOR: legacy strict disabled-feature list and isolation checker

export const STRICT_CODEX_DISABLED_FEATURES = Object.freeze([
  'shell_tool',
  'browser_use',
  'browser_use_external',
  'browser_use_full_cdp_access',
  'computer_use',
  'multi_agent',
  'multi_agent_v2'
]);

const TOOL_EVENT_TYPES = new Set([
  'tool_use',
  'tool_result',
  'command_execution',
  'mcp_tool_call',
  'web_search',
  'web_search_request',
  'web_fetch',
  'file_search',
  'computer_use',
  'shell'
]);

export function inspectWorkerIsolation(stdout) {
  const events = [];
  let malformedLines = 0;
  const visit = (value) => {
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (!value || typeof value !== 'object') return;
    const type = typeof value.type === 'string' ? value.type.toLowerCase() : '';
    if (TOOL_EVENT_TYPES.has(type)) {
      events.push({
        type,
        name: String(value.name || value.tool_name || value.toolName || value.command || '').slice(0, 160) || null
      });
    }
    for (const nested of Object.values(value)) visit(nested);
  };
  const raw = String(stdout || '');
  try {
    visit(JSON.parse(raw));
  } catch {
    for (const line of raw.split('\n')) {
      if (!line.trim()) continue;
      try { visit(JSON.parse(line)); } catch { malformedLines++; }
    }
  }
  const reasons = [];
  if (events.length) reasons.push('WORKER_TOOL_CALL');
  if (malformedLines) reasons.push('WORKER_TRANSCRIPT_UNPARSEABLE');
  return {
    status: events.length === 0 && malformedLines === 0 ? 'PASS' : 'FAIL',
    toolCalls: events,
    malformedLines,
    reasons
  };
}

The legacy code has no hook, installed-skill, plugin, memory, app, goal,
tool-suggestion, or workspace-dependency context check.

